package engagement

import (
	"testing"
	"time"

	"rdpshot/internal/model"
)

func TestBuildManifestStableHash(t *testing.T) {
	scan := model.Scan{ID: "scan_1", Name: "demo", Engagement: "acme"}
	files := map[string][]byte{
		"meta.json":     []byte(`{"ok":true}`),
		"findings.csv":  []byte("a,b\n"),
		"report.html":   []byte("<html></html>"),
	}
	m1, err := BuildManifest(scan, files)
	if err != nil {
		t.Fatal(err)
	}
	// Force same Generated by rebuilding quickly is non-deterministic; ensure files hashed.
	if len(m1.Files) != 3 {
		t.Fatalf("files=%d", len(m1.Files))
	}
	if m1.ManifestSHA256 == "" {
		t.Fatal("missing manifest hash")
	}
	if m1.Generated.After(time.Now().UTC().Add(time.Minute)) {
		t.Fatal("generated timestamp in future")
	}
}
